#include <iostream>
struct Shape {                                  // 抽象类（含纯虚函数）
    virtual double area() const = 0;
    virtual ~Shape() = default;
};
struct Square : Shape {
    double s;
    explicit Square(double x) : s(x) {}
    double area() const override { return s * s; }
};
int main() {
    // Shape sh;          // 编译错误：不能实例化抽象类
    Square sq(3);
    Shape& r = sq;        // 通过抽象基类接口操作
    std::cout << r.area();
}
